#!/bin/sh
set -eu
# Directory must contain standalone, optional, fixture, synthetic.yaml and
# smoke-data generated by make-smoke-data.py. Outputs are written here.
cd "${1:?Usage: board-micro-ros-options.sh TEST_DIRECTORY}"
./standalone synthetic.yaml smoke-data/stereo.csv smoke-data/imu.csv baseline.csv > baseline.log 2>&1
./optional synthetic.yaml smoke-data/stereo.csv smoke-data/imu.csv default-off.csv > default-off.log 2>&1
SCHUR_MICRO_ROS=0 SCHUR_MICRO_ROS_AGENT=invalid ./optional synthetic.yaml smoke-data/stereo.csv smoke-data/imu.csv explicit-off.csv > explicit-off.log 2>&1
SCHUR_MICRO_ROS=1 SCHUR_MICRO_ROS_AGENT=192.168.123.2 SCHUR_MICRO_ROS_PORT=18889 ./optional synthetic.yaml smoke-data/stereo.csv smoke-data/imu.csv agent-absent.csv > agent-absent.log 2>&1
for name in default-off explicit-off agent-absent; do cmp baseline.csv "$name.csv"; done
if SCHUR_MICRO_ROS=1 ./standalone --self-test synthetic.yaml > not-compiled.log 2>&1; then exit 1; fi
grep -q 'not compiled in' not-compiled.log
if SCHUR_MICRO_ROS=1 ./optional --self-test synthetic.yaml > missing-agent.log 2>&1; then exit 1; fi
grep -q 'numeric IPv4' missing-agent.log
if SCHUR_MICRO_ROS=yes ./optional --self-test synthetic.yaml > invalid-enable.log 2>&1; then exit 1; fi
grep -q 'must be 0 or 1' invalid-enable.log
SCHUR_MICRO_ROS=0 ./fixture 30 > disabled-fixture.log 2>&1 &
pid=$!
sleep 1
threads=$(ls /proc/$pid/task | wc -l)
[ "$threads" -eq 1 ]
ls -l /proc/$pid/fd > disabled-fds.log
if grep -q 'socket:' disabled-fds.log; then exit 1; fi
wait "$pid"
echo 'DISABLED: one thread, no sockets'
SCHUR_MICRO_ROS=1 SCHUR_MICRO_ROS_AGENT=192.168.123.2 SCHUR_MICRO_ROS_PORT=18889 ./fixture 30 > absent-fixture.log 2>&1 &
pid=$!
sleep 1
threads=$(ls /proc/$pid/task | wc -l)
[ "$threads" -eq 2 ]
wait "$pid"
echo 'ENABLED: two threads; no Agent required to finish'
sha256sum baseline.csv default-off.csv explicit-off.csv agent-absent.csv
grep 'frames=' baseline.log default-off.log explicit-off.log agent-absent.log
echo 'BOARD OPTIONAL MICRO-ROS CHECKS PASS'
